def kruskal(n, edges):                     # edges: (weight, u, v)
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False                   # already connected: this edge makes a cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        rank[ra] += rank[ra] == rank[rb]
        return True

    tree, total = [], 0
    for w, u, v in sorted(edges):          # the sort dominates: O(E log E)
        if union(u, v):
            tree.append((u, v, w))
            total += w
    return tree, total
